      "subgoal": "Explain what empirical evaluation is and where it fits in the system implementation lifecycle after code testing."
    },
    {
      "start": 24,
      "subgoal": "Explain why limited expert or user prototype evaluations are insufficient for conclusive usability assessment and identify the requirements of a full empirical usability study."
    },
    {
      "start": 45,
      "subgoal": "List and describe the four stages of an empirical or usability study."
    },
    {
      "start": 67,
      "subgoal": "Explain how to formulate research questions for an empirical usability study by contrasting vague, comparative, and testable questions and using multiple testable questions to answer broader untestable questions."
    },
    {
      "start": 186,
      "subgoal": "Describe how to identify independent and dependent variables and levels in an empirical usability experiment using a text-entry interface example."
    },
    {
      "start": 211,
      "subgoal": "Summarize the main points of the lecture, including the empirical study context, the first two stages, and the remaining stages."
    }
  ]
}

